param([string]$RunId='nps_vatd_cuda_rank_v1',[string]$OutputRoot=(Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..')).Path 'artifacts\nps_sota_research\nps_vatd_cuda_rank_v1_runner'))
$pidFile=Join-Path $OutputRoot "$RunId.pid";$metaFile=Join-Path $OutputRoot "$RunId.meta.txt";$progressFile=Join-Path $OutputRoot 'progress.json';$pidValue=if(Test-Path $pidFile){Get-Content $pidFile|Select-Object -First 1}else{$null};$process=if($pidValue){Get-Process -Id $pidValue -ErrorAction SilentlyContinue}else{$null};$status=if($process){'RUNNING'}else{'NOT RUNNING'};Write-Host "$status PID=$pidValue";if(Test-Path $progressFile){$p=Get-Content $progressFile -Raw|ConvertFrom-Json;Write-Host "status=$($p.stage) done=$($p.done)/$($p.total) last_output_timestamp=$($p.updated)"}else{Write-Host 'status=not_started done=0/2 last_output_timestamp=none'};if(Test-Path $metaFile){Get-Content $metaFile};$outDir=Join-Path (Split-Path $OutputRoot -Parent) 'nps_vatd_cuda_rank_v1';if(Test-Path (Join-Path $outDir 'fusion_sweep.json')){$o=Get-Content (Join-Path $outDir 'fusion_sweep.json') -Raw|ConvertFrom-Json;Write-Host "last_completed_unit=evaluation best_map50=$($o.best.map50) best_recall=$($o.best.recall)"}elseif(Test-Path (Join-Path $outDir 'train_summary.json')){Write-Host 'last_completed_unit=train'}else{Write-Host 'last_completed_unit=none'};$meta=if(Test-Path $metaFile){Get-Content $metaFile}else{@()};foreach($kind in @('stdout','stderr')){$line=$meta|Where-Object{$_ -like ($kind+'=*')}|Select-Object -First 1;if($line){$path=$line.Substring($kind.Length+1);Write-Host ($kind+'='+$path);if(Test-Path $path){Get-Content $path -Tail 12}}}
